1	//! Authorized-devices store + host key for the embedded SSH sync server.
2	//!
3	//! Both live under `<app_data_dir>/local_sync/`: the Ed25519 host key as an
4	//! OpenSSH private key file, and the paired phone keys as `devices.json`.
5	//! Everything is exchanged as OpenSSH text so the ssh-key/russh crate versions
6	//! never have to agree on binary types.
7	
8	use serde::{Deserialize, Serialize};
9	use std::fs;
10	use std::path::{Path, PathBuf};
11	
12	use crate::{app_data_dir, now_ms, AppEnv};
13	use rand_core::{OsRng, RngCore};
14	use ssh_key::{Algorithm, HashAlg, LineEnding, PrivateKey};
15	
16	const LOCAL_SYNC_DIR: &str = "local_sync";
17	const HOST_KEY_FILE: &str = "host_key";
18	const DEVICES_FILE: &str = "devices.json";
19	
20	/// One paired device (a phone whose key may use the sync server).
21	#[derive(Clone, Serialize, Deserialize)]
22	pub struct PairedDevice {
23	    pub name: String,
24	    /// `"<algorithm> <base64>"` — an OpenSSH public key line without comment.
25	    pub public_key: String,
26	    pub added_ms: i64,
27	}
28	
29	fn local_sync_dir(app: &AppEnv) -> Result<PathBuf, String> {
30	    let dir = app_data_dir(app)?.join(LOCAL_SYNC_DIR);
31	    fs::create_dir_all(&dir).map_err(|e| e.to_string())?;
32	    Ok(dir)
33	}
34	
35	pub(super) fn devices_path(app: &AppEnv) -> Result<PathBuf, String> {
36	    Ok(local_sync_dir(app)?.join(DEVICES_FILE))
37	}
38	
39	/// Load (or create on first use) the server host key. Returns the OpenSSH
40	/// private key text and the `SHA256:...` public key fingerprint that clients
41	/// pin via the QR code.
42	pub(super) fn ensure_host_key(app: &AppEnv) -> Result<(String, String), String> {
43	    let path = local_sync_dir(app)?.join(HOST_KEY_FILE);
44	    if path.exists() {
45	        let content = fs::read_to_string(&path).map_err(|e| e.to_string())?;
46	        let key = PrivateKey::from_openssh(&content)
47	            .map_err(|e| format!("Sync server host key is unreadable: {e}"))?;
48	        let fingerprint = key.public_key().fingerprint(HashAlg::Sha256).to_string();
49	        return Ok((content, fingerprint));
50	    }
51	    let mut key = PrivateKey::random(&mut OsRng, Algorithm::Ed25519)
52	        .map_err(|e| format!("Failed to generate the sync server host key: {e}"))?;
53	    key.set_comment("type-local-sync-host");
54	    let content = key
55	        .to_openssh(LineEnding::LF)
56	        .map_err(|e| format!("Failed to encode the sync server host key: {e}"))?
57	        .to_string();
58	    fs::write(&path, content.as_bytes()).map_err(|e| e.to_string())?;
59	    #[cfg(unix)]
60	    {
61	        use std::os::unix::fs::PermissionsExt;
62	        let _ = fs::set_permissions(&path, fs::Permissions::from_mode(0o600));
63	    }
64	    let fingerprint = key.public_key().fingerprint(HashAlg::Sha256).to_string();
65	    Ok((content, fingerprint))
66	}
67	
68	/// Random pairing token for one server run (hex, QR-safe).
69	pub(super) fn generate_pairing_token() -> String {
70	    let mut bytes = [0u8; 16];
71	    OsRng.fill_bytes(&mut bytes);
72	    bytes.iter().map(|b| format!("{b:02x}")).collect()
73	}
74	
75	pub(super) fn list_devices(path: &Path) -> Vec<PairedDevice> {
76	    if !path.exists() {
77	        return Vec::new();
78	    }
79	    fs::read_to_string(path)
80	        .ok()
81	        .and_then(|content| serde_json::from_str(&content).ok())
82	        .unwrap_or_default()
83	}
84	
85	/// Normalize an OpenSSH public key line to `"<algorithm> <base64>"` (drops the
86	/// comment so lookups don't depend on it).
87	pub(super) fn normalize_key_line(line: &str) -> Option<String> {
88	    let mut fields = line.split_whitespace();
89	    let algorithm = fields.next()?;
90	    let base64 = fields.next()?;
91	    Some(format!("{algorithm} {base64}"))
92	}
93	
94	pub(super) fn is_authorized(path: &Path, key_line: &str) -> bool {
95	    list_devices(path)
96	        .iter()
97	        .any(|device| device.public_key == key_line)
98	}
99	
100	pub(super) fn register_device(path: &Path, key_line: &str, name: &str) -> Result<(), String> {
101	    let mut devices = list_devices(path);
102	    if devices.iter().any(|device| device.public_key == key_line) {
103	        return Ok(());
104	    }
105	    devices.push(PairedDevice {
106	        name: name.to_string(),
107	        public_key: key_line.to_string(),
108	        added_ms: now_ms().unwrap_or(0),
109	    });
110	    let content = serde_json::to_string_pretty(&devices).map_err(|e| e.to_string())?;
111	    fs::write(path, content).map_err(|e| e.to_string())
112	}
113	
114	/// The comment-less key line for a key offered over SSH (russh's re-exported
115	/// ssh-key version may differ from ours, so go through OpenSSH text).
116	pub(super) fn public_key_line(key: &russh::keys::PublicKey) -> Option<String> {
117	    normalize_key_line(&key.to_openssh().ok()?)
118	}
119	
120	/// Human label for a pairing device: the key comment when present.
121	pub(super) fn device_name_from_key(key: &russh::keys::PublicKey) -> String {
122	    let comment = key.comment().to_string();
123	    if comment.trim().is_empty() {
124	        "Phone".to_string()
125	    } else {
126	        comment
127	    }
128	}
