134	    #[test]
135	    fn registers_and_authorizes_devices() {
136	        let dir = std::env::temp_dir().join(format!("type-devices-{}", generate_pairing_token()));
137	        fs::create_dir_all(&dir).unwrap();
138	        let path = dir.join(DEVICES_FILE);
139	
140	        let key_line = "ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIP///w";
141	        assert!(!is_authorized(&path, key_line));
142	        register_device(&path, key_line, "iPhone").unwrap();
143	        assert!(is_authorized(&path, key_line));
144	        // Idempotent.
145	        register_device(&path, key_line, "iPhone").unwrap();
146	        assert_eq!(list_devices(&path).len(), 1);
147	
148	        fs::remove_dir_all(&dir).unwrap();
149	    }
150	
151	    #[test]
152	    fn normalizes_key_lines() {
153	        assert_eq!(
154	            normalize_key_line("ssh-ed25519 QUJD my comment").as_deref(),
155	            Some("ssh-ed25519 QUJD")
156	        );
157	        assert_eq!(normalize_key_line("ssh-ed25519"), None);
158	    }
